  [CustomMarket.proto_celo_v3]: onNetwork('Celo'),
  [CustomMarket.proto_gnosis_v3]: onNetwork('Gnosis'),
  [CustomMarket.proto_ink_v3]: onNetwork('Ink'),
  [CustomMarket.proto_linea_v3]: onNetwork('Linea'),
